export const NETWORK_BY_ID: ReadonlyMap<string, NetVessel> = new Map(NETWORK.map((v) => [v.id, v]));
/** Edge IDs the anatomy draws as vessels: what a parity row counts. */
export const DRAWN_EDGE_IDS: readonly string[] = edges.filter(isDrawnEdge).map((e) => e.id);
/** Drawn only once the paraumbilical collateral has opened (the 2D rule). */
export const NEEDS_C3_IDS = NEEDS_C3;

// ---- presence ----
export type Presence = 'shown' | 'ghost' | 'hidden';
export interface PresenceFrame { Q: ArrayLike<number>; Qf?: ArrayLike<number>; D: ArrayLike<number> }
export interface PresenceOptions { /** Blood menu: Potential collaterals (dotted routes that open with pressure) */ collaterals: boolean; /** the Circuit is showing or on its way: the liver's beds are drawn on the map (the body leaves them out) */ circuit?: boolean }
const OPEN_FRAC = 0.12, OPEN_Q = 0.3, C3_FRAC = 0.15, AP_Q = 0.3;
const indexOf = new Map(edges.map((e, i) => [e.id, i]));

/** ONE SEGMENT (Mohammad, 22 Nov: "coronary vein -> azygos through varices, the entire thing one segment: opens and closes as one"). The engine cuts a collateral route in edges where its stations are (the coronary vein to the varices,
 *  the varices to the azygos) and gives them one `code`: edges of one code that meet end to end are one vessel to draw. Nothing here names C1: any route the engine splits gets the same treatment. Member ids, in flow order, by member. */
export const SEGMENT_OF: ReadonlyMap<string, readonly string[]> = (() => {
  const byCode = new Map<string, Edge[]>();
  for (const e of edges) if (e.kind === 'collateral' && e.code) byCode.set(e.code, [...(byCode.get(e.code) ?? []), e]);
  const m = new Map<string, readonly string[]>();
  for (const list of byCode.values()) {
    if (list.length < 2) continue;
    const chain: Edge[] = [list.find((e) => !list.some((o) => o !== e && o.to === e.from)) ?? list[0]!];
    while (chain.length < list.length) { const nx = list.find((o) => !chain.includes(o) && o.from === chain[chain.length - 1]!.to); if (!nx) break; chain.push(nx); }
    if (chain.length < list.length) continue;   // (not one run end to end: separate vessels)
    const ids = chain.map((e) => e.id);
    for (const id of ids) m.set(id, ids);
  }
  return m;
})();
/** Whether two collateral edges are neighbours in one segment (they meet at its station: the one vessel's two halves). */
export const sameSegment = (a: string, b: string): boolean => a !== b && !!SEGMENT_OF.get(a)?.includes(b);
const recruitOwn = (k: number, f: PresenceFrame): number => { const e = edges[k]!, lo = dMinOf(e) as number, hi = e.dMax ?? lo; return hi > lo ? Math.min(1, Math.max(0, (f.D[k]! - lo) / (hi - lo))) : 0; };
/** How far a collateral has opened, 0 to 1, from its diameter between its closed and open ones (stage-frame.js recruitFrac). A segment opens as one: every member reads the most open of them. */
export function recruitFrac(id: string, f: PresenceFrame): number {
  return Math.max(...(SEGMENT_OF.get(id) ?? [id]).map((m) => recruitOwn(indexOf.get(m)!, f)));
}
/** Whether a collateral is drawn open: it has grown past an eighth, or carries 0.3 mL/s. A segment is open when any of it is, and closed when all of it is. */
export function collateralOpen(id: string, f: PresenceFrame): boolean {
  return recruitFrac(id, f) > OPEN_FRAC || (SEGMENT_OF.get(id) ?? [id]).some((m) => Math.abs((f.Qf ?? f.Q)[indexOf.get(m)!]!) > OPEN_Q);
}

/** The shunts an operation sews in (not the stents): with one in place the closed potential collaterals are not drawn as dotted threads, which stood as stray stubs beside the shunt's ends (Mohammad, 22 Nov: "stray dotted stub"). */
export const SURGICAL_SHUNT_IDS: readonly string[] = ['S_PC', 'S_MC', 'S_DSR', 'REX'];
const surgicalShuntIn = (f: PresenceFrame): boolean => SURGICAL_SHUNT_IDS.some((id) => { const k = indexOf.get(id); return k != null && (f.D[k]! > 0 || drawnDiameter(id) > 0); });

/** The 2D rules of stage-frame.js edgeVisible: a collateral is solid once open, a dotted thread while closed when potential collaterals are on, and nothing
 *  otherwise; the epigastric veins appear with the paraumbilical collateral; an arterioportal shunt only while it carries flow. */
export function presenceOf(v: Pick<NetVessel, 'id' | 'kind' | 'feeder'>, f: PresenceFrame, o: PresenceOptions, healthyQ?: ArrayLike<number>): Presence {
  if (v.feeder) return feederLive(v.feeder, f, healthyQ) > 0 ? 'shown' : 'hidden';
  const k = indexOf.get(v.id);
  if (k == null) return 'hidden';
  if (NEEDS_C3.has(v.id)) return recruitFrac('C3', f) > C3_FRAC ? 'shown' : 'hidden';
  // (the lumbar-azygos collateral C9 runs through the right sinusoid fan: while closed it is not drawn as a dotted pink thread there; Mohammad, 20 Nov)
  // the sinusoid beds (the "light bulb" fans, their feeding arterioles and their strands) are not drawn: the portal veins fade out into the liver and the hepatic veins fade in from it,
  // and the liver tissue implies the sinusoids between (Mohammad, 20 Nov). They stay in the network (the flows, the labels and the Lobule read them), only never shown.
  // (the Circuit draws them: 2D's map shows the portal venules dividing and the sinusoids gathering, and Mohammad wants them there, 20 Nov)
  if (v.kind === 'liver') return o.circuit ? 'shown' : 'hidden';
  if (v.kind === 'collateral') return collateralOpen(v.id, f) ? 'shown' : o.collaterals && v.id !== 'C9' && !surgicalShuntIn(f) ? 'ghost' : 'hidden';
  if (SHUNT_IDS.has(v.id)) return f.D[k]! > 0 || drawnDiameter(v.id) > 0 ? 'shown' : 'hidden';   // a procedure's shunt is there while it has a diameter
  if (v.kind === 'shunt') return (f.Qf ?? f.Q)[k]! > AP_Q ? 'shown' : 'hidden';
  return 'shown';
}

/** How far a tributary group is on, 0 to 1 (stage-tubes.js feeders): the epigastric network fills in as the paraumbilical route opens; the caudate vein's own collaterals
 *  as its flow rises to twice and then four times the healthy one; the rest always. */
export function feederLive(fd: { host: string; when: string | null }, f: PresenceFrame, healthyQ?: ArrayLike<number>): number {
  if (fd.when === 'caput' || fd.when === 'umb') return Math.min(1, Math.max(0, (recruitFrac('C3', f) - 0.15) / 0.3));
  if (fd.when === 'caudate') {
    const k = indexOf.get(fd.host)!, ref = healthyQ?.[k], q = Math.abs((f.Qf ?? f.Q)[k]!);
    return ref ? Math.min(1, Math.max(0, (q / Math.abs(ref) - 2) / 2)) : 0;
  }
  return 1;
}
